Section Walk.
  Variable AL : asan_layout.
  Hypothesis IMG : asan_img_ok AL.
  Hypothesis ALWF : al_wf AL.
  Local Instance lxi : LxImg asegs AL := lxA_img AL IMG.
  Variable CS : Z -> Prop.
  Hypothesis CSOK : cs_ok AL CS.
  Variables (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word)
            (F : bvmap 5 word) (fc : bv 32) (m : mem)
            (D dl S sl slm ld ls lo b : Z) (ds0 ss : list word).
  Hypothesis Hdl : 0 <= dl <= 10000.
  Hypothesis Hsl : 0 <= sl <= 10000.
  Hypothesis Hslm : 0 <= slm /\ slm <= dl /\ slm <= sl.
  Hypothesis Ln : dl <= ld /\ sl <= ls.
  Hypothesis L0 : Z.of_nat (length ds0) = ld.
  Hypothesis LS : Z.of_nat (length ss) = ls.
  Hypothesis DB : 0 < D /\ D + 4 * ld <= 2^64.
  Hypothesis SB0 : 0 <= S /\ S + 4 * ls <= 2^64.
  Hypothesis DTOP : D + 4 * ld < 2^64.
  Hypothesis STOP : S + 4 * ls < 2^64.
  Hypothesis NZS : sl = 0 \/ 0 < S.
  Hypothesis SPR : 0 <= bv_unsigned sp < 2^64.
  Hypothesis LO0 : 0 <= lo.
  Hypothesis LO : lo <= bv_unsigned sp - 112.
  Hypothesis SCS : crange CS lo (bv_unsigned sp - lo).
  Hypothesis SX : D + 4 * ld <= bv_unsigned sp - 112 \/ bv_unsigned sp <= D.
  Hypothesis SSX : S + 4 * ls <= bv_unsigned sp - 112 \/ bv_unsigned sp <= S.
  Hypothesis RA : bv_unsigned ra mod 2 = 0.
  Hypothesis ALD : D mod 4 = 0.
  Hypothesis ALS : S mod 4 = 0.
  Hypothesis HB : 0 <= b < 2^32.

  Hypothesis SLM : slm = Z.min dl sl.

  Notation POST := (mpi_core_mla_vpostA asegs ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc D dl ds0 sl ss b lo m).
  Notation W := [(D, D + 4 * dl); (bv_unsigned sp - 112, bv_unsigned sp)].
  Notation SP' := (Z_to_bv 64 (bv_unsigned sp + -112)).
  Notation SB := (Z_to_bv 64 (al_sb AL)).
  Notation FRAME mm cl := (rw_cells asegs mm (bv_unsigned sp + -112) [cl; C8 s11; C8 s10; C8 s9; C8 s8; C8 s7; C8 s6; C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra]).
  Notation SFACT mm := ((S = D /\ ss = ds0) \/ (bytes_at asegs mm S (u32s ss) /\ (S + 4 * ls <= D \/ D + 4 * ld <= S))).
  Notation DINV mm ds := (u32arr asegs mm D ds /\ Z.of_nat (length ds) = ld
                          /\ munch W m mm /\ wmono asegs m mm /\ mem_inv asegs mm /\ stk asegs mm lo (bv_unsigned sp + -112)).
  (* [comment removed for export] *)
  Notation VINV ds i k c wc := (same_from (Z.to_nat i) ds ds0 /\ 0 <= c < 2^32 /\ bv_unsigned wc = sxz c
                                /\ lval ds i + 2^(32*i) * c = lval ds0 i + lval ss k * b).
  Notation AOBJ mm := (aobj asegs AL CS mm D (4 * dl) /\ aobj asegs AL CS mm S (4 * slm)).

  (* [comment removed for export] *)
  (* [comment removed for export] *)
  Ltac mla_next HBb :=
    match goal with
    | CUR : ?cu = sxz ?c, RNG : 0 <= ?cc < 2 ^ 32,
      DEF : ?cu2 = zlow 64 (zswrap 32 (zlow 32 (zlow 64 (zlow 32 (bv_unsigned ?v) * ?bb) ≫ 32 + (Z.b2z (zlow 64 _ <? ?cu) + _)))) |- _ =>
        constr_eq c cc;
        let cn := fresh "c" in let CUR2 := fresh "CUR" in let RNG2 := fresh "RNG" in let V := fresh "VS" in
        (flat constr:((lx_mla_step _ _ _ c cu cu2 HBb RNG CUR DEF)) 4%nat; intros cn CUR2 RNG2 V);
        clear CUR RNG DEF; rename CUR2 into CUR; rename RNG2 into RNG
    end.
  (* [comment removed for export] *)
  Ltac mla_wc :=
    match goal with
    | R1 : 0 <= ?cu, R2 : 0 <= - ?cu' + 18446744073709551615, CUR : ?cu'' = sxz _ |- _ =>
        constr_eq cu cu'; constr_eq cu cu''; pose proof (lx_wc_sxz _ _ R1 R2 CUR) as WC'
    | CUR : bv_unsigned ?w = sxz _ |- _ => pose proof CUR as WC'; rewrite <- (Z_to_bv_bv_unsigned w) in WC' at 1
    end.
  (* [comment removed for export] *)
  Ltac mla_ret EI EK LXh SFh RNGh VIh :=
    lx_post;
    [> eassumption
     | rewrite ?upd_length; xlia LXh L0
     | apply same_from_skipn; [rewrite <- EI; exact SFh | rewrite ?upd_length; xlia LXh L0]
     | exact RNGh
     | rewrite <- SLM, <- EI; try rewrite <- EK; exact VIh
     | .. ].


  Lemma vframe_C8_CB : forall mm w, FRAME mm (C8 w) -> FRAME mm (CB 8 (le8 w)).
  Proof.
    intros mm w [[WF HF] WR]. split; [split|]; [ split; [apply length_le8 | exact (proj2 WF)] | exact HF | exact WR ].
  Qed.

  Lemma ml_exc_step : forall (wd : word) (c cu sm : Z),
    0 <= c < 2^32 -> cu = sxz c -> sm = cu + zswrap 32 (zlow 32 (bv_unsigned wd)) ->
    0 <= Z.b2z (zlow 64 (zswrap 32 (zlow 32 sm)) <? cu) < 2^32
    /\ w32 (Z_to_bv 64 (zswrap 32 (zlow 32 sm))) + 2^32 * Z.b2z (zlow 64 (zswrap 32 (zlow 32 sm)) <? cu) = w32 wd + c
    /\ bv_unsigned (Z_to_bv 64 (Z.b2z (zlow 64 (zswrap 32 (zlow 32 sm)) <? cu)))
       = sxz (Z.b2z (zlow 64 (zswrap 32 (zlow 32 sm)) <? cu)).
  Proof.
    intros wd c cu sm Hc Ecu Esm. subst sm.
    pose proof (Z.mod_pos_bound (bv_unsigned wd) (2^32) ltac:(lia)) as Rd.
    unfold w32. change (zlow 32 (bv_unsigned wd)) with (bv_unsigned wd mod 2^32).
    set (d := bv_unsigned wd mod 2^32) in *.
    pose proof (lx_sxz_cases c Hc) as Ec. rewrite <- Ecu in Ec.
    destruct (lx_s32_cases d ltac:(lia)) as [Ed _].
    assert (Er : zlow 32 (cu + zswrap 32 d) = (c + d) mod 2^32).
    { unfold zlow. rewrite Ec, Ed. destruct (c <? 2^31); destruct (d <? 2^31);
      first [reflexivity | rewrite <- (Z.mod_add _ 1) by lia; f_equal; lia | rewrite <- (Z.mod_add _ (1 - 2^32)) by lia; f_equal; lia
            | rewrite <- (Z.mod_add _ (2 - 2^32)) by lia; f_equal; lia]. }
    rewrite !Er. pose proof (Z.mod_pos_bound (c + d) (2^32) ltac:(lia)) as Rr. set (r := (c + d) mod 2^32) in *.
    destruct (lx_s32_cases r ltac:(lia)) as [Erz Ur]. rewrite !Ur.
    assert (E1 : ((if r <? 2^31 then r else r + 2^64 - 2^32) <? cu) = (r <? c)).
    { rewrite Ec. clear - Rr Hc. destruct (Z.ltb_spec r (2^31)); destruct (Z.ltb_spec c (2^31)); destruct (Z.ltb_spec r c);
      first [reflexivity | apply Z.ltb_lt; lia | apply Z.ltb_ge; lia]. }
    rewrite !E1.
    assert (Err : r = c + d - (if c + d <? 2^32 then 0 else 2^32)).
    { subst r. clear - Hc Rd. destruct (Z.ltb_spec (c + d) (2^32)). rewrite Z.mod_small; lia. rewrite <- (Z.mod_add _ (-1)) by lia. rewrite Z.mod_small; lia. }
    split; [destruct (r <? c); cbn; lia|]. split.
    - rewrite Z_to_bv_unsigned. change (bv_wrap 64 (zswrap 32 r)) with (zlow 64 (zswrap 32 r)). rewrite Ur.
      replace ((if r <? 2 ^ 31 then r else r + 2 ^ 64 - 2 ^ 32) mod 2 ^ 32) with r.
      2:{ clear - Rr. destruct (r <? 2^31). rewrite Z.mod_small; lia. rewrite <- (Z.mod_add _ (1 - 2^32)) by lia. rewrite Z.mod_small; lia. }
      clearbody r d. clear - Hc Rd Rr Err. destruct (Z.ltb_spec r c); destruct (Z.ltb_spec (c + d) (2^32)); cbn [Z.b2z]; lia.
    - rewrite Z_to_bv_unsigned. unfold sxz. destruct (r <? c); reflexivity.
  Qed.

  Ltac ml_exc dx c RNG CUR :=
    lazymatch goal with
    | |- context [Z.b2z (zlow 64 (zswrap 32 (zlow 32 ?sm)) <? ?cu)] =>
        flat constr:((ml_exc_step dx c cu sm RNG CUR ltac:(first [reflexivity | apply Z.add_comm]))) 3%nat;
        intros RNG' V' WC'; clear RNG
    end.

  (* [comment removed for export] *)
  Local Ltac2 Set LiaOrc.tbl := fun () => "". (* [comment removed for export] *)
  Lemma vexcess_walk : forall (k : nat) (i ex en c : Z) (ds : list word) (mm : mem) (jk : list byte)
      (xra xt0 xt2 xs1 xa3 xa5 wc xa7 xs2 xs3 xs4 xs5 xs6 xs7 xs8 xs9 xs10 xs11 xt3 xt4 xt5 xt6 wa2 wa4 : word),
    Z.to_nat (dl - i) = k -> slm <= i < dl -> ex = D + 4 * i -> en = i - dl ->
    wa2 = Z_to_bv 64 (-5) -> wa4 = Z_to_bv 64 0 ->
    DINV mm ds -> AOBJ mm -> FRAME mm (CB 8 jk) -> VINV ds i slm c wc ->
    evtA asegs AL CS POST
      (MS (mkR xra SP' gp tp xt0 SB xt2 (Z_to_bv 64 ex) xs1 (Z_to_bv 64 ex) (Z_to_bv 64 en) wa2 xa3 wa4 xa5 wc xa7
               xs2 xs3 xs4 xs5 xs6 xs7 xs8 xs9 xs10 xs11 xt3 xt4 xt5 xt6)
          F (Z_to_bv 64 0xa515c) fc None mm (seg_rom asegs)).
  (* [comment removed for export] *)
  Proof.
    induction k as [|k IH]; intros i ex en c ds mm jk xra xt0 xt2 xs1 xa3 xa5 wc xa7 xs2 xs3 xs4 xs5 xs6 xs7 xs8 xs9 xs10 xs11 xt3 xt4 xt5 xt6 wa2 wa4
      Hk Hi Ex En -> -> (HX & LX0 & MU & WM & MI & ST) [OD OS] FR (FS & RNG & CUR & VI); [exfalso; xlia Hk Hi|].
    pose proof (cs_ok_sb _ _ CSOK) as SB64.
    lx_limb_rw HX i Ex ltac:(xlia Hi Hslm) ltac:(xlia Hi Hslm Ln LX0) dx NX.
    lx_hide HX. lx_hide MU. lx_hide WM. lx_hide VI.
