    all: pose proof (u32arr_upd_of_cell _ _ _ _ _ _ _ _ HX NX ltac:(xlia Hi Hslm) Ex MUl WMl CX') as HX';
         pose proof (munch_local1 _ _ _ _ _ _ _ _ _ eq_refl MU MUl ltac:(xlia Ex Hi Hslm) ltac:(xlia Ex Hi)) as MU';
         pose proof (wmono_trans _ _ _ _ WM WMl) as WM';
