  Lemma vx1_walk : forall (k : nat) (i es ed e7 eb c : Z) (ds : list word) (mm : mem) (jk : list byte)
      (xra xs0 xs1 wc xs2 xs3 xs4 xs5 xs6 xs7 xs8 xs9 xs10 xs11 wt3 wt4 wt5 wt6 : word),
    Z.to_nat (slm - i) = k -> 0 <= i < slm -> es = S + 4 * i -> ed = D + 4 * i -> e7 = slm - i -> eb = b ->
    wt3 = Z_to_bv 64 0 -> wt4 = Z_to_bv 64 0 -> wt5 = Z_to_bv 64 5 -> wt6 = Z_to_bv 64 (-5) ->
    DINV mm ds -> SFACT mm -> AOBJ mm -> FRAME mm (CB 8 jk) -> VINV ds i i c wc ->
    evtA asegs AL CS POST
      (MS (mkR xra SP' gp tp (Z_to_bv 64 eb) SB (Z_to_bv 64 slm) xs0 xs1 (Z_to_bv 64 ed) (Z_to_bv 64 dl) (Z_to_bv 64 es) (Z_to_bv 64 sl)
               (Z_to_bv 64 ed) (Z_to_bv 64 es) wc (Z_to_bv 64 e7)
