      Hk Hi Es Ed E7 Eb -> -> -> -> (HX & LX0 & MU & WM & MI & ST) AS [OD OS] FR (FS & RNG & CUR & VI); [exfalso; xlia Hk Hi|].
    subst eb. pose proof (cs_ok_sb _ _ CSOK) as SB64.
    assert (SPOS : 0 < S) by (clear - NZS Hi Hslm; lia).
    destruct (lx_sview mm D S ld ls i ds ds0 ss HX LX0 L0 FS LS ltac:(xlia Hi) AS) as (sv & HSV & LSV & AS3 & VSV & RSV). clear AS.
    lx_limb_rw HX i Ed ltac:(xlia Hi) ltac:(xlia Hi Hslm Ln LX0) dx NX.
    pose proof (u32ro_cellq mm S sv i es HSV ltac:(xlia Hi) ltac:(xlia Hi Hslm Ln LSV) Es) as CSx.
    remember (nth (Z.to_nat i) sv w0) as vx eqn:Hvx in CSx.
    lx_hide HX. lx_hide HSV. lx_hide MU. lx_hide WM. lx_hide VSV. lx_hide Hvx. lx_hide VI.
    lx_run_tac (PLAN [0xa5088; 0xa515c] [(0xa50b0, DJoin); (0xa50c4, DJoin)] 100%N); lx_tree.
