  Lemma vx8_walk : forall (k : nat) (j n8 i e2 eb c : Z) (ds : list word) (mm : mem)
      (xra xt0 wc xa4 xa5 xa7 xs6 xs7 xs8 xs9 xs10 xs11 xt3 wb wt4 ws0 ws1 ws2 ws3 ws4 ws5 : word),
    Z.to_nat (n8 - j) = k -> 0 <= j < n8 -> 8 * n8 <= slm -> slm - 8 * n8 = slm mod 8 -> i = 8 * j -> e2 = n8 - j -> eb = b ->
    wt4 = Z_to_bv 64 (32 * j) -> ws0 = Z_to_bv 64 0 -> ws1 = Z_to_bv 64 0 -> ws2 = Z_to_bv 64 4 ->
    ws3 = Z_to_bv 64 (Z.shiftr D 3 + al_sb AL + 4 * j) -> ws4 = Z_to_bv 64 (Z.shiftr S 3 + al_sb AL + 4 * j) ->
    ws5 = Z_to_bv 64 (-5) ->
    DINV mm ds -> SFACT mm -> AOBJ mm -> FRAME mm (C8 wb) -> Z.shiftr (bv_unsigned wb) 32 = b -> VINV ds i i c wc ->
    evtA asegs AL CS POST
      (MS (mkR xra SP' gp tp xt0 SB (Z_to_bv 64 slm) ws0 ws1 (Z_to_bv 64 D) (Z_to_bv 64 dl) (Z_to_bv 64 S) (Z_to_bv 64 sl)
               xa4 xa5 wc xa7 ws2 ws3 ws4 ws5 xs6 xs7 xs8 xs9 xs10 xs11 xt3 wt4 (Z_to_bv 64 e2) (Z_to_bv 64 eb))
          F (Z_to_bv 64 0xa4b80) fc None mm (seg_rom asegs)).
  (* [comment removed for export] *)
  Proof.
    induction k as [|k IH]; intros j n8 i e2 eb c ds mm xra xt0 wc xa4 xa5 xa7 xs6 xs7 xs8 xs9 xs10 xs11 xt3 wb wt4 ws0 ws1 ws2 ws3 ws4 ws5
      Hk Hj Hn8 Hr Hi E2 Eb -> -> -> -> -> -> -> (HX & LX & MU & WM & MI & ST) AS [OD OS] FR HWB (FS & RNG & CUR & VI0); [exfalso; xlia Hk Hj|].
    subst eb. pose proof (cs_ok_sb _ _ CSOK) as SB64.
    assert (SPOS : 0 < S) by (clear - NZS Hj Hn8 Hslm; lia).
    (* [comment removed for export] *)
    destruct (lx_sview mm D S ld ls i ds ds0 ss HX LX L0 FS LS ltac:(xlia Hj Hi) AS) as (sv & HSV & LSV & AS3 & VSV & RSV). clear AS.
    pose proof (u32rw_cells8 mm D ds i (D + 32 * j) HX ltac:(xlia Hj Hi) ltac:(xlia Hj Hi Hn8 Hslm Ln LX) ltac:(xlia Hi)) as CD.
    remember (nth (Z.to_nat i) ds w0) as d0 eqn:Hd0 in CD. remember (nth (Z.to_nat (i + 1)) ds w0) as d1 eqn:Hd1 in CD.
    remember (nth (Z.to_nat (i + 2)) ds w0) as d2 eqn:Hd2 in CD. remember (nth (Z.to_nat (i + 3)) ds w0) as d3 eqn:Hd3 in CD.
    remember (nth (Z.to_nat (i + 4)) ds w0) as d4 eqn:Hd4 in CD. remember (nth (Z.to_nat (i + 5)) ds w0) as d5 eqn:Hd5 in CD.
    remember (nth (Z.to_nat (i + 6)) ds w0) as d6 eqn:Hd6 in CD. remember (nth (Z.to_nat (i + 7)) ds w0) as d7 eqn:Hd7 in CD.
    let sc q e v CSq Hv := (pose proof (u32ro_cellq mm S sv q e HSV ltac:(xlia Hj Hi) ltac:(xlia Hj Hi Hn8 Hslm Ln LSV) ltac:(xlia Hi)) as CSq;
                            remember (nth (Z.to_nat q) sv w0) as v eqn:Hv in CSq) in
    sc i (S + 32 * j) v0 CS0 Hv0; sc (i + 1) (S + 32 * j + 4) v1 CS1 Hv1; sc (i + 2) (S + 32 * j + 8) v2 CS2 Hv2;
    sc (i + 3) (S + 32 * j + 12) v3 CS3 Hv3; sc (i + 4) (S + 32 * j + 16) v4 CS4 Hv4; sc (i + 5) (S + 32 * j + 20) v5 CS5 Hv5;
    sc (i + 6) (S + 32 * j + 24) v6 CS6 Hv6; sc (i + 7) (S + 32 * j + 28) v7 CS7 Hv7.
    lx_hide HX. lx_hide HSV. lx_hide MU. lx_hide WM. lx_hide VSV. lx_hide VI0.
    lx_hide Hd0. lx_hide Hd1. lx_hide Hd2. lx_hide Hd3. lx_hide Hd4. lx_hide Hd5. lx_hide Hd6. lx_hide Hd7.
    lx_hide Hv0. lx_hide Hv1. lx_hide Hv2. lx_hide Hv3. lx_hide Hv4. lx_hide Hv5. lx_hide Hv6. lx_hide Hv7.
    lx_run_tac (PLAN [0xa4b80; 0xa5088; 0xa515c]
      [(0xa4ba4, DJoin); (0xa4bb0, DJoin); (0xa4bc0, DJoin); (0xa4be4, DJoin); (0xa4bfc, DJoin); (0xa4c0c, DJoin); (0xa4c4c, DJoin);
       (0xa4c64, DJoin); (0xa4c78, DJoin); (0xa4cb8, DJoin); (0xa4cd0, DJoin); (0xa4ce4, DJoin); (0xa4d24, DJoin); (0xa4d3c, DJoin);
       (0xa4d50, DJoin); (0xa4d90, DJoin); (0xa4da8, DJoin); (0xa4dbc, DJoin); (0xa4dfc, DJoin); (0xa4e14, DJoin); (0xa4e28, DJoin);
       (0xa4e70, DJoin); (0xa4e88, DJoin)] 450%N); lx_tree.
    all: lx_unhide; lx_gc.
    (* [comment removed for export] *)
    all: do 8 (mla_next HB).
    all: let vstep i1 i2 dK vK HdK HvK :=
      (let L1 := fresh "L" in let L2 := fresh "L" in
       assert (L1 : limb32 ds0 (Z.to_nat i1) = w32 dK)
         by (eapply (limb32_same_from_nth ds ds0 i); [exact FS | xlia Hj Hi | xlia Hj Hi Hn8 Hslm Ln LX | xlia LX L0 | exact HdK]);
       assert (L2 : limb32 ss (Z.to_nat i1) = w32 vK)
         by (eapply VSV; [xlia Hj Hi | xlia Hj Hi Hn8 Hslm Ln LSV | exact HvK]);
       match goal with
       | VI : lval ?dsk i1 + _ * ?c = _, VS : _ + 2 ^ 32 * ?c' = w32 dK + w32 vK * _ + ?cc |- _ =>
           constr_eq c cc; rewrite <- L1, <- L2 in VS;
           let VI2 := fresh "VI" in
           pose proof (vi_mul_stepZ dsk ds0 ss i1 i2 _ c c' _ ltac:(xlia Hj Hi) ltac:(rewrite ?upd_length; xlia Hj Hi Hn8 Hslm Ln LX) ltac:(xlia0) VI VS) as VI2;
           clear VI VS L1 L2
       end) in
      vstep i (i + 1) d0 v0 Hd0 Hv0; vstep (i + 1) (i + 2) d1 v1 Hd1 Hv1;
      vstep (i + 2) (i + 3) d2 v2 Hd2 Hv2; vstep (i + 3) (i + 4) d3 v3 Hd3 Hv3;
      vstep (i + 4) (i + 5) d4 v4 Hd4 Hv4; vstep (i + 5) (i + 6) d5 v5 Hd5 Hv5;
      vstep (i + 6) (i + 7) d6 v6 Hd6 Hv6; vstep (i + 7) (i + 8) d7 v7 Hd7 Hv7.
    all: lx_rn_rw (D + 32 * j) CD'; lx_rn_munch MUl; lx_rn_wmono WMl; lx_rn_mi MI'; lx_rn_stk ST'; lx_rn_aobj D OD'; lx_rn_aobj S OS';
         try lx_rn_rw (bv_unsigned sp + -112) FR'.
    all: pose proof (u32arr_upd8_of_cells mm lxm D ds i (D + 32 * j) _ _ _ _ _ _ _ _ _ HX ltac:(xlia Hj Hi) ltac:(xlia Hj Hi Hn8 Hslm Ln LX) ltac:(xlia Hi) MUl ltac:(xlia0) WMl CD') as HX';
         pose proof (RSV lxm _ _ MUl ltac:(xlia Hj) ltac:(xlia Hj Hn8 Hslm Ln)) as AS';
         pose proof (munch_local1 _ _ _ _ _ _ _ _ _ eq_refl MU MUl ltac:(xlia Hj) ltac:(xlia Hj Hn8 Hslm Ln)) as MU';
         pose proof (wmono_trans _ _ _ _ WM WMl) as WM'.
    all: lazymatch type of HX' with u32arr _ _ _ ?ds8 =>
           assert (SF : same_from (Z.to_nat (i + 8)) ds8 ds0) by (apply same_from_upd8_Z; [exact FS | xlia Hj Hi | xlia0]);
           assert (LX' : Z.of_nat (length ds8) = ld) by (rewrite !upd_length; exact LX) end.
    all: mla_wc.
    all: lazymatch goal with VI : lval _ _ + _ * _ = _ |- evtA _ _ _ _ (MS _ _ ?pcw _ _ _ _) =>
      lazymatch pcw with
      | Z_to_bv 64 0xa4b80 =>
         (* [comment removed for export] *)
         eapply (IH (j + 1) n8 (i + 8));
         first [ exact (conj HX' (conj LX' (conj MU' (conj WM' (conj MI' ST'))))) | exact AS' | exact (conj OD' OS') | exact FR'
               | exact (conj SF (conj RNG (conj WC' VI))) | ml_side ]
      | Z_to_bv 64 0xa5088 =>
         (* [comment removed for export] *)
         assert (EN : i + 8 = 8 * n8) by ml_lia;
         eapply (vx1_walk (Z.to_nat (slm - (i + 8))) (i + 8));
         first [ exact (conj HX' (conj LX' (conj MU' (conj WM' (conj MI' ST'))))) | exact AS' | exact (conj OD' OS')
               | exact (vframe_C8_CB _ _ FR') | exact (conj SF (conj RNG (conj WC' VI))) | ml_side ]
      | Z_to_bv 64 0xa515c =>
         (* [comment removed for export] *)
         assert (EI : i + 8 = slm) by ml_lia;
         eapply (vexcess_walk (Z.to_nat (dl - slm)) slm);
         first [ exact (conj HX' (conj LX' (conj MU' (conj WM' (conj MI' ST'))))) | exact (conj OD' OS')
               | exact (vframe_C8_CB _ _ FR') | rewrite <- EI; exact (conj SF (conj RNG (conj WC' VI))) | ml_side ]
      | ret_pc _ =>
         (* [comment removed for export] *)
         assert (EI : i + 8 = dl) by ml_lia; assert (EK : i + 8 = slm) by ml_lia;
         mla_ret EI EK LX SF RNG VI
      end end.
    all: match goal with |- ?g => idtac "VX8-LEFT:" g end.
  Qed.
